const item = $input.first();
// If Cloudflare already returned a binary image, pass it through
if (item.binary && item.binary.data) {
  return [{ json: { imageReady: true }, binary: { data: item.binary.data } }];
}
const res = item.json || {};
const b64 = (res.result && res.result.image) || res.image;
if (!b64) {
  throw new Error('Cloudflare returned no image. Response: ' + JSON.stringify(res).slice(0, 500));
}
const bin = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'post-image.jpg', 'image/jpeg');
return [{ json: { imageReady: true }, binary: { data: bin } }];

const cfg = $('Config').first().json;
if (/^PASTE/.test(cfg.myProfile || '') || /^PASTE/.test(cfg.myGoals || '') || /^PASTE/.test(cfg.cloudflareAccountId || '')) throw new Error('Fill myProfile, myGoals and cloudflareAccountId in the Config1 node first');
const topics = $input.all().map(i => i.json).filter(r => r.Topic).map(r => String(r.Topic));
return [{ json: { previousTopics: topics.length ? topics.slice(-60).join('; ') : 'None yet', topicList: topics } }];

