const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2);
const out = $input.first().json.output;
if (!out || !out.topic) throw new Error('Topic Agent returned no topic');
const words = new Set(norm(out.topic));
for (const t of $('Build History').first().json.topicList) {
  const w = new Set(norm(t));
  const inter = [...words].filter(x => w.has(x)).length;
  const union = new Set([...words, ...w]).size || 1;
  if (inter / union >= 0.6) throw new Error('Duplicate topic: ' + out.topic);
}
return [{ json: { topic: out.topic, audience: out.audience, angle: out.angle } }];

